const cache = new Map();
let calls = 0;
function fib(n) {
    calls++;
    if (n < 2) return n;
    if (cache.has(n)) return cache.get(n);
    const result = fib(n - 1) + fib(n - 2);
    cache.set(n, result);
    return result;
}
console.log(fib(30));
console.log("chaqiruvlar:", calls);
console.log("keshda:", cache.size);

