function findDuplicates(items) {
    const seen = new Set();
    const duplicates = new Set();
    for (const item of items) {
        if (seen.has(item)) {
            duplicates.add(item);
        } else {
            seen.add(item);
        }
    }
    return [...duplicates];
}
console.log(findDuplicates([1, 2, 3, 2, 4, 3, 2, 5]));
console.log(findDuplicates(["a", "b", "c"]));

const graph = {
    A: ["B", "C"],
    B: ["A", "D"],
    C: ["A", "D"],
    D: ["B", "C"],
};
function traverse(start) {
    const visited = new Set();
    const stack = [start];
    while (stack.length > 0) {
        const node = stack.pop();
        if (visited.has(node)) continue;
        visited.add(node);
        for (const next of graph[node]) {
            stack.push(next);
        }
    }
    return [...visited];
}
console.log(traverse("A"));

