function longestStreak(numbers) {
    const set = new Set(numbers);
    let best = 0;
    for (const n of set) {
        if (set.has(n - 1)) continue;
        let length = 1;
        while (set.has(n + length)) length++;
        best = Math.max(best, length);
    }
    return best;
}
