function countNodes(root) {
    const visited = new WeakSet();
    function walk(node) {
        if (visited.has(node)) return 0;
        visited.add(node);
        let count = 1;
        for (const next of node.links) count += walk(next);
        return count;
    }
    return walk(root);
}
