// HTML: <div id="card"></div>
const handlers = new WeakMap();
const card = document.getElementById("card");
function listen(element, type, fn) {
    element.addEventListener(type, fn);
    const list = handlers.get(element) ?? [];
    list.push([type, fn]);
    handlers.set(element, list);
}
function unlistenAll(element) {
    for (const [type, fn] of handlers.get(element) ?? []) {
        element.removeEventListener(type, fn);
    }
    handlers.delete(element);
}
listen(card, "click", () => console.log("click"));
listen(card, "mouseover", () => console.log("hover"));
console.log(handlers.get(card).length);
unlistenAll(card);
console.log(handlers.has(card));

