function addBusinessDays(date, count) {
    const result = new Date(date);
    let left = count;
    while (left > 0) {
        result.setUTCDate(result.getUTCDate() + 1);
        const day = result.getUTCDay();
        if (day !== 0 && day !== 6) left--;
    }
    return result;
}

