function neumaierSum(values) {
    let sum = 0;
    let compensation = 0;
    for (const value of values) {
        const t = sum + value;
        compensation += Math.abs(sum) >= Math.abs(value) ? sum - t + value : value - t + sum;
        sum = t;
    }
    return sum + compensation;
}

